1	'use client';
2	// 用到 React hook 或 Base UI 的模組標成 client 元件，Next App Router 的伺服器元件才能匯入套件入口（PR-ADOPT-01）。
3	import {Select as BaseSelect} from '@base-ui/react/select';
4	import {Checkbox as BaseCheckbox} from '@base-ui/react/checkbox';
5	import {Input as BaseInput} from '@base-ui/react/input';
6	import {Button} from './button.js';
7	import {usePortalContainer} from './theme.js';
8	import {Children, Fragment, isValidElement, useId, type ChangeEvent, type HTMLAttributes, type InputHTMLAttributes, type OptionHTMLAttributes, type SelectHTMLAttributes, type ReactNode} from 'react';
9	
10	type FieldDetails = {label:string; error?:string; helper?:string};
11	export type TextFieldProps = InputHTMLAttributes<HTMLInputElement> & FieldDetails;
12	export function TextField({label,error,helper,id:providedId,className='',...props}:TextFieldProps) {
13	  const generatedId=useId();
14	  const id=providedId ?? generatedId;
15	  const description=error ?? helper;
16	  const describedBy=[props['aria-describedby'],description ? `${id}-description` : undefined].filter(Boolean).join(' ') || undefined;
17	  return <div className="luca-field"><label htmlFor={id}>{label}</label><BaseInput {...props} className={`luca-input ${className}`.trim()} id={id} aria-invalid={error ? true : props['aria-invalid']} aria-describedby={describedBy}/>{description && <span id={`${id}-description`} className={error ? 'luca-field-error' : 'luca-field-helper'}>{description}</span>}</div>;
18	}
19	// Select 以 Base UI 的 Select 實作（ADR 0006），公開 props 沿用 0.1.0 原生 select 的寫法：
20	// 選項仍以 <option> 子元素描述，onChange 仍收到 event.target.value。多選與列高沒有對應的自訂選單行為，故移除（升級說明有列）。
21	type SelectValue = string | number;
22	export type SelectProps = Omit<SelectHTMLAttributes<HTMLSelectElement>, 'multiple' | 'size' | 'value' | 'defaultValue' | 'onChange'> & FieldDetails & {
23	  value?:SelectValue;
24	  defaultValue?:SelectValue;
25	  // 只帶 target／currentTarget 的 value、name 與 id，不是瀏覽器原生的 change 事件。
26	  onChange?:(event:ChangeEvent<HTMLSelectElement>) => void;
27	};
28	type SelectOption = {value:string; label:string; disabled:boolean};
29	// 文字內容攤平成字串；<option> 沒有 value 時與原生相同，以文字當值。
30	const textOf = (node:ReactNode):string => Children.toArray(node).map(child => typeof child === 'string' || typeof child === 'number' ? String(child) : isValidElement<{children?:ReactNode}>(child) ? textOf(child.props.children) : '').join('');
31	// Fragment 內的 <option> 也讀（Children.toArray 不會攤平 Fragment）；<optgroup> 與其他元素略過（升級說明有列）。
32	function readOptions(children:ReactNode):SelectOption[] {
33	  return Children.toArray(children).flatMap((child):SelectOption[] => {
34	    if (isValidElement<{children?:ReactNode}>(child) && child.type === Fragment) return readOptions(child.props.children);
35	    if (!isValidElement<OptionHTMLAttributes<HTMLOptionElement>>(child) || child.type !== 'option') return [];
36	    const label = child.props.label ?? textOf(child.props.children);
37	    return [{value:child.props.value === undefined ? label : String(child.props.value), label, disabled:Boolean(child.props.disabled)}];
38	  });
39	}
40	export function Select({label,error,helper,id:providedId,className='',children,value,defaultValue,onChange,name,disabled,required,form,autoComplete,...props}:SelectProps) {
41	  const generatedId=useId();
42	  const id=providedId ?? generatedId;
43	  const description=error ?? helper;
44	  const describedBy=[props['aria-describedby'],description ? `${id}-description` : undefined].filter(Boolean).join(' ') || undefined;
45	  const container=usePortalContainer();
46	  const options=readOptions(children);
47	  // 原生 select 未給值時選第一個可選項，這裡照做，欄位才不會空白。
48	  const initial=defaultValue === undefined ? options.find(option => !option.disabled)?.value ?? null : String(defaultValue);
49	  const change=(next:string|null) => {
50	    const target={value:next ?? '', name:name ?? '', id};
51	    onChange?.({target, currentTarget:target, type:'change'} as unknown as ChangeEvent<HTMLSelectElement>);
52	  };
53	  return <div className="luca-field"><label htmlFor={id}>{label}</label>
54	    <BaseSelect.Root id={id} items={options} value={value === undefined ? undefined : String(value)} defaultValue={value === undefined ? initial : undefined} onValueChange={change} name={name} disabled={disabled} required={required} form={form} autoComplete={autoComplete}>
55	      {/* 其餘屬性（aria-*、data-*、焦點事件等）交給欄位按鈕；事件的 currentTarget 因此是 button。 */}
56	      <BaseSelect.Trigger {...props as HTMLAttributes<HTMLButtonElement>} id={id} className={`luca-input luca-select-trigger ${className}`.trim()} aria-invalid={error ? true : props['aria-invalid']} aria-describedby={describedBy}>
57	        <BaseSelect.Value className="luca-select-value"/>
58	        <BaseSelect.Icon className="luca-select-icon"><svg viewBox="0 0 18 18" width="18" height="18" aria-hidden="true"><path d="M4.5 6.75 9 11.25l4.5-4.5" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round"/></svg></BaseSelect.Icon>
59	      </BaseSelect.Trigger>
60	      <BaseSelect.Portal container={container ?? undefined}>
61	        {/* 選單與欄位同寬、貼齊欄位下緣 4px（§5.5.2）；不採 Base UI 預設的「選中項對齊欄位」位置。 */}
62	        <BaseSelect.Positioner className="luca-select-positioner" side="bottom" align="start" sideOffset={4} alignItemWithTrigger={false}>
63	          <BaseSelect.Popup className="luca-select-popup">
64	            {options.map((option,index) => <BaseSelect.Item key={index} value={option.value} label={option.label} disabled={option.disabled} className="luca-select-option">
65	              <BaseSelect.ItemText>{option.label}</BaseSelect.ItemText>{option.disabled && '（不可選）'}
66	            </BaseSelect.Item>)}
67	          </BaseSelect.Popup>
68	        </BaseSelect.Positioner>
69	      </BaseSelect.Portal>
70	    </BaseSelect.Root>
71	    {description && <span id={`${id}-description`} className={error ? 'luca-field-error' : 'luca-field-helper'}>{description}</span>}</div>;
72	}
73	// Checkbox 以 Base UI 的 Checkbox 實作（ADR 0006）：可見的方框是 role="checkbox" 的節點，旁邊另有隱藏的 <input> 負責表單送出。
74	// 公開 props 沿用 0.1.0 原生 input 的寫法，onChange 仍收到 event.target.checked；與原生事件的差異見升級說明。
75	// hideLabel 只在視覺上隱藏標籤文字（PR-STYLE-60）：文字仍在 <label> 內，方框的名稱照舊來自 label。
76	export type CheckboxProps = Omit<InputHTMLAttributes<HTMLInputElement>,'type'> & FieldDetails & {hideLabel?:boolean};
77	export function Checkbox({label,hideLabel=false,error,helper,id:providedId,className='',checked,defaultChecked,disabled,required,readOnly,name,form,value,onChange,...props}:CheckboxProps) {
78	  const generatedId=useId();
79	  const id=providedId ?? generatedId;
80	  const description=error ?? helper;
81	  const describedBy=[props['aria-describedby'],description ? `${id}-description` : undefined].filter(Boolean).join(' ') || undefined;
82	  const change=(next:boolean) => {
83	    const target={checked:next, value:value === undefined ? 'on' : String(value), name:name ?? '', id};
84	    onChange?.({target, currentTarget:target, type:'change'} as unknown as ChangeEvent<HTMLInputElement>);
85	  };
86	  return <div className="luca-field"><label className="luca-checkbox" htmlFor={id}>
87	    {/* 其餘屬性（aria-*、data-*、焦點事件等）交給方框節點；事件的 currentTarget 因此是該節點而不是 input。 */}
88	    <BaseCheckbox.Root {...props as HTMLAttributes<HTMLSpanElement>} id={id} className={`luca-checkbox-box ${className}`.trim()} checked={checked} defaultChecked={defaultChecked} disabled={disabled} required={required} readOnly={readOnly} name={name} form={form} value={value === undefined ? undefined : String(value)} onCheckedChange={change} aria-invalid={error ? true : props['aria-invalid']} aria-describedby={describedBy}>
89	      <BaseCheckbox.Indicator className="luca-checkbox-indicator"><svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true"><path d="m3.5 8.5 3 3 6-7" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg></BaseCheckbox.Indicator>
90	    </BaseCheckbox.Root>{hideLabel ? <span className="luca-visually-hidden">{label}</span> : label}</label>{description && <span id={`${id}-description`} className={error ? 'luca-field-error' : 'luca-field-helper'}>{description}</span>}</div>;
91	}
92	export type StatusTone = 'success' | 'warning' | 'error';
93	const statusLabels={success:'成功',warning:'警告',error:'錯誤'};
94	// label 取代語氣前綴（PR-STYLE-59）；不提供拿掉前綴，否則語氣只剩顏色表達，所以空字串也退回預設。
95	export type StatusMessageProps = {tone:StatusTone; label?:string; children:ReactNode};
96	export function StatusMessage({tone,label,children}:StatusMessageProps) {
97	  return <div className={`luca-status luca-status-${tone}`} role={tone === 'error' ? 'alert' : 'status'}>{label || statusLabels[tone]} · {children}</div>;
98	}
99	// title、description、retryLabel 取代預設文字（PR-STYLE-59），沒給時沿用下方的中文預設。
100	// retryLabel 給空字串也退回「重試」，按鈕才不會沒有名稱；description 的空字串照舊保留（頁面會用它清空說明）。
101	export type ContentStateProps = {state:'loading'|'empty'|'error'; title?:string; description?:string; retryLabel?:string; onRetry?:()=>void};
102	export function ContentState({state,title,description,retryLabel,onRetry}:ContentStateProps) {
103	  const titles={loading:'內容載入中',empty:'目前沒有可顯示的內容',error:'內容載入失敗'};
104	  return <div className="luca-content-state" role={state === 'error' ? 'alert' : 'status'} aria-busy={state === 'loading'}>{state === 'loading' && <span className="luca-loading-animation" aria-hidden="true"/>}<h3>{title ?? titles[state]}</h3><p>{description ?? (state === 'loading' ? '正在準備內容，請稍候。' : state === 'empty' ? '內容準備好後會顯示於此。' : '請重試以重新顯示內容。')}</p>{state === 'error' && onRetry && <Button variant="secondary" onClick={onRetry}>{retryLabel || '重試'}</Button>}</div>;
105	}
