1	'use client';
2	// 用到 React hook 或 Base UI 的模組標成 client 元件，Next App Router 的伺服器元件才能匯入套件入口（PR-ADOPT-01）。
3	import {NavigationMenu} from '@base-ui/react/navigation-menu';
4	import {useRender} from '@base-ui/react/use-render';
5	import type {AnchorHTMLAttributes, ReactElement, ReactNode, Ref} from 'react';
6	export type NavigationItem={label:string;href:string};
7	// renderLink 收到的屬性（PR-STYLE-57）：<a> 的屬性加 ref，href 一定有值。專案把它們展開到自己的連結元件上。
8	export type NavigationLinkProps=AnchorHTMLAttributes<HTMLAnchorElement>&{href:string;ref?:Ref<HTMLAnchorElement>};
9	export type NavigationProps={items:NavigationItem[];currentPath?:string;brand?:string;brandHref?:string;label?:string;renderLink?:(props:NavigationLinkProps)=>ReactElement};
10	// Navigation 以 Base UI 的 NavigationMenu 實作（ADR 0006）；只有連結，沒有子選單，所以只用 Root、List、Item、Link（Link 的 active 會帶 aria-current="page"）。
11	// 品牌連結不屬於選單項目（Link 必須在 List 內），改用 Base UI 的 useRender 渲染，才能同樣交給 renderLink。
12	// renderLink 只收函式：元素寫法的 props 會蓋過內部的 href，所有項目會連到同一頁。
13	export function Navigation({items,currentPath,brand='Luca Style /',brandHref='/',label='主要導覽',renderLink}:NavigationProps) {
14	  const render=renderLink && ((props:object)=>renderLink(props as NavigationLinkProps));
