*, *::before, *::after { box-sizing: border-box; }
html, body { margin: 0; overflow-x: hidden; }
body { background: var(--bg); color: var(--text); font-family: var(--font-body, Inter, 'Noto Sans TC', sans-serif); line-height: 1.6; }
.app-main { max-width: 1200px; margin: 0 auto; padding: var(--space-6) var(--space-4); display: grid; gap: var(--space-4); min-width: 0; }
.app-main h1 { margin: 0; font-size: 2rem; line-height: 1.3; }
.app-main section { display: grid; gap: var(--space-4); min-width: 0; }
.app-main p { margin: 0; }
.app-toolbar { display: grid; grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) auto; gap: var(--space-4); align-items: end; }
.app-count, .app-none { color: var(--muted); font-size: .875rem; }
.app-none { padding: var(--space-6); background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-card); text-align: center; }
.app-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.app-table { width: 100%; border-collapse: collapse; background: var(--surface); border: 1px solid var(--border); font-size: .875rem; }
.app-table th, .app-table td { padding: var(--space-3) var(--space-4); border-bottom: 1px solid var(--border); text-align: left; vertical-align: middle; overflow-wrap: anywhere; }
.app-table th { color: var(--muted); font-weight: 600; background: var(--surface-subtle); }
.app-num { text-align: right !important; font-variant-numeric: tabular-nums; }
.app-badge { display: inline-block; padding: 0 var(--space-3); border: 1px solid currentColor; border-radius: 999px; background: var(--surface); font-size: .8125rem; font-weight: 600; white-space: nowrap; }
.app-badge-pending { color: var(--warning); }
.app-badge-paid { color: var(--success); }
.app-badge-shipped { color: var(--accent-hover, var(--accent)); }
.app-badge-cancelled { color: var(--muted); }
.app-row-actions, .app-actions { display: flex; gap: var(--space-2); flex-wrap: wrap; }
.app-row-actions .luca-button { padding-inline: var(--space-4); }
.app-actions { justify-content: flex-end; }
.app-dialog { width: min(480px, calc(100vw - 2rem)); max-height: calc(100vh - 2rem); padding: var(--space-6); border: 1px solid var(--border); border-radius: var(--radius-card); background: var(--surface); color: var(--text); overflow-y: auto; }
.app-dialog::backdrop { background: rgb(0 0 0 / .5); }
.app-form { display: grid; gap: var(--space-4); }
.app-form h2 { margin: 0; font-size: 1.25rem; }
.app-form p { color: var(--text); }

@media (max-width: 900px) {
  .app-toolbar { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .app-toolbar > .luca-button { grid-column: 1 / -1; }
  .app-table, .app-table tbody, .app-table tr, .app-table td { display: block; }
  .app-table { border: 0; background: transparent; }
  .app-table thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
  .app-table tr { margin-bottom: var(--space-3); background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius-card); padding: var(--space-2) 0; }
  .app-table td { display: grid; grid-template-columns: 6rem minmax(0, 1fr); gap: var(--space-3); border: 0; padding: var(--space-2) var(--space-4); text-align: left; }
  .app-table td::before { content: attr(data-label); color: var(--muted); font-weight: 600; }
  .app-num { text-align: left !important; }
}
@media (max-width: 520px) {
  .app-toolbar { grid-template-columns: minmax(0, 1fr); }
  .app-main h1 { font-size: 1.5rem; }
}

